  if(n.id==='appearancePreset'){const sets={explorer:{ageLook:'adult woman',hairColor:'wavy chestnut',hairStyle:'loose',build:'athletic adult build',outfit:'Copper flight jacket, dark trousers, sturdy boots',tattoos:[{design:'constellation',colors:'',style:'fine line',size:'small',placement:'forearm'}]},noir:{ageLook:'adult man',hairColor:'sleek dark',hairStyle:'combed back',build:'tall adult build',outfit:'Charcoal trench coat over a fully buttoned shirt',tattoos:[{design:'geometric sleeve',colors:'black',style:'blackwork',size:'full sleeve',placement:'left arm'}]},artist:{ageLook:'adult woman',hairColor:'silver',hairTexture:'curly',hairStyle:'loose',build:'soft, strong adult build',outfit:'Rolled-sleeve linen shirt and high-waisted trousers',tattoos:[{design:'flowers',colors:'watercolor',style:'traditional',size:'medium',placement:'shoulder'}]}};const chosen=sets[n.value];if(!chosen||!draft)return;draft=collectCharacter();draft.look=normalizeLook({...draft.look,...chosen,tattoos:chosen.tattoos||draft.look.tattoos});drawCharacterForm();}
